746	        await checkAdmin();
747	        const supabase = await createAdminClient();
748	
749	        const { data: obMembers, error: fetchError } = await supabase
750	            .from('members')
751	            .select('supabase_auth_user_id, discord_uid')
752	            .eq('status', 2)
753	            .is('deleted_at', null)
754	            .not('discord_uid', 'is', null);
755	
756	        if (fetchError) throw new Error(`OB/OGメンバーの取得に失敗: ${fetchError.message}`);
757	        if (!obMembers || obMembers.length === 0) {
758	            return { error: null, message: 'OB/OGメンバーが見つかりませんでした。' };
759	        }
760	
