762	        if (usersError) throw new Error(`ユーザー情報の取得に失敗: ${usersError.message}`);
763	
764	        const userMap = new Map(allUsers.map(u => [u.id, u]));
765	
766	        let successCount = 0;
767	        let failCount = 0;
768	
769	        for (const member of obMembers) {
